package com.multitenanterp.payroll;
import java.math.*;import java.time.*;import java.time.temporal.ChronoUnit;
final class PayrollProrationCalculator{
 static PayrollProration calculate(YearMonth period,String basis,LocalDate joining,LocalDate exit,BigDecimal unpaid,BigDecimal absent,int overtime){LocalDate start=period.atDay(1),end=period.atEndOfMonth();LocalDate eligibleStart=joining.isAfter(start)?joining:start;LocalDate eligibleEnd=exit!=null&&exit.isBefore(end)?exit:end;long calendarEligible=eligibleEnd.isBefore(eligibleStart)?0:ChronoUnit.DAYS.between(eligibleStart,eligibleEnd)+1;BigDecimal periodDays=BigDecimal.valueOf("FIXED_30".equals(basis)?30:period.lengthOfMonth());BigDecimal eligibleDays=BigDecimal.valueOf(calendarEligible);if("FIXED_30".equals(basis)&&joining.isBefore(start.plusDays(1))&&(exit==null||!exit.isBefore(end)))eligibleDays=periodDays;BigDecimal deductions=nonNegative(unpaid).add(nonNegative(absent));BigDecimal payable=eligibleDays.subtract(deductions).max(BigDecimal.ZERO).min(periodDays);BigDecimal factor=periodDays.signum()==0?BigDecimal.ZERO:payable.divide(periodDays,8,RoundingMode.HALF_UP);return new PayrollProration(periodDays,eligibleDays,nonNegative(unpaid),nonNegative(absent),payable,factor,Math.max(0,overtime));}
 private static BigDecimal nonNegative(BigDecimal value){return value==null?BigDecimal.ZERO:value.max(BigDecimal.ZERO);}
}
